function keRupiah(nilai: unknown): string {
  if (typeof nilai === "number") return "Rp" + nilai.toLocaleString("id-ID");
  if (typeof nilai === "string" && nilai.trim() !== "" && !Number.isNaN(Number(nilai))) {
    return "Rp" + Number(nilai).toLocaleString("id-ID");
  }
  return "format harga tidak dikenal";
}

